.visible .entry layer_norm_kernel(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 sum_ptr,
    .param .u64 sqsum_ptr,
    .param .u32 n_param,
    .param .f32 eps_param,
    .param .u32 seg_size_param
)
{
    .reg .pred   %p<10>;
    .reg .b32    %r<40>;
    .reg .f32    %f<40>;
    .reg .b64    %rd<40>;
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [y_ptr];
    ld.param.u64 %rd3, [w_ptr];
    ld.param.u64 %rd4, [b_ptr];
    ld.param.u64 %rd5, [sum_ptr];
    ld.param.u64 %rd6, [sqsum_ptr];
    ld.param.u32 %r1, [n_param];
    ld.param.f32 %f1, [eps_param];
    ld.param.u32 %r2, [seg_size_param];
