    add.s32 %r8, %r7, %r2;
    min.s32 %r9, %r8, %r1;
    min.s32 %r7, %r7, %r1;
    sub.s32 %r10, %r9, %r7;
    shr.u32 %r11, %r10, 2;
    shl.b32 %r12, %r11, 2;
    add.s32 %r13, %r7, %r12;
    mov.u32 %r14, %r5;
