    sub.f32 %f24, %f12, %f5;
    mul.f32 %f24, %f24, %f10;
    fma.rn.f32 %f24, %f24, %f16, %f20;
    sub.f32 %f25, %f13, %f5;
    mul.f32 %f25, %f25, %f10;
