    .reg .b32    %r<50>;
    .reg .f32    %f<50>;
    .reg .b64    %rd<70>;

    .shared .align 4 .f32 s_sum[1024];
    .shared .align 4 .f32 s_sq[1024];

    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [y_ptr];
    ld.param.u64 %rd3, [w_ptr];
    ld.param.u64 %rd4, [b_ptr];
    ld.param.u32 %r1, [n_param];
    ld.param.f32 %f1, [eps_param];

