    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f2;
    shfl.sync.down.b32 %r34, %r33, 2, 31, 0xffffffff;
    mov.b32 %f41, %r34;
    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f2;
    shfl.sync.down.b32 %r34, %r33, 1, 31, 0xffffffff;
