    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 16, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 8, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 4, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    mov.b32 %r33, %f3;
